    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, directed, closed;
    cin >> n >> m >> directed >> closed;
    HamiltonDP g(n);
    for (int i = 0, a, b; i < m; i++) {
        cin >> a >> b;
        g.add(--a, --b);
        if (!directed) g.add(b, a);
    }
    auto ans = g.solve(closed);
    if (ans.empty()) cout << "IMPOSSIBLE\n";
    else {
        for (int u : ans) cout << u + 1 << ' ';
        cout << '\n';
    }
}

